/* =====================================================================
   admin.js — Keuangan SPP, Materi, Laporan, WhatsApp & Notifikasi, CRM, Pengguna, Berita, Migrasi, Pengaturan
   ===================================================================== */
'use strict';
const tabsHtml = (items, aktif) => `<div class="chips mb" role="tablist">${items.map(i => `<button class="chip ${i[0] === aktif ? 'on' : ''}" role="tab" data-tab="${i[0]}">${i[1]}</button>`).join('')}</div>`;
const kpiHtml = (l, ik, val, foot, cls) => `<div class="card kpi"><div class="l"><span>${l}</span><span class="ico">${ico(ik)}</span></div><div class="v ${cls || ''}">${val}</div><div class="sub">${foot || ''}</div></div>`;

/* ---------- Keuangan SPP ---------- */
function pageKeuangan(v) {
  let rows = [], tab = 'verif', f = { periode: bulanIni(), status: '', q: '' }, mati = false;
  v.innerHTML = judul('Administrasi', 'Manajemen Keuangan & Verifikasi SPP', `<button class="btn primary" id="tb">${ico('add_card', 'sm')} Terbitkan tagihan</button><button class="btn" id="exp">${ico('download', 'sm')} Ekspor CSV</button>`) + '<div id="kv">' + `<div class="grid g4">${skelCards(4)}</div>` + '</div>';
  const draw = () => {
    if (mati) return; const bln = rows.filter(k => k.Periode === bulanIni()), lunas = bln.filter(k => k.Status === 'Lunas');
    const menunggu = rows.filter(k => k.Status === 'Menunggu'), belum = bln.filter(k => k.Status === 'Belum Bayar' || k.Status === 'Ditolak');
    const tot = lunas.reduce((a, k) => a + Number(k.Nominal), 0), target = bln.reduce((a, k) => a + Number(k.Nominal), 0);
    const cardBukti = k => `<div class="card flat bukti-card"><div class="row between"><span class="faint mono" style="font-size:11px">${esc(k.ID_Transaksi)}</span>${badgeBayar(k.Status)}</div><div class="nm">${esc(k.Nama)}<small>${esc(k.Kelas)} · ${esc(k.Jenis_Iuran)} ${periodeID(k.Periode)}</small></div><div style="font:700 22px var(--font-h);color:var(--primary)">${rp(k.Nominal)}</div>
      <div class="row wrap">${urlAman(k.URL_Bukti) ? `<a class="btn sm" target="_blank" rel="noopener" href="${esc(urlAman(k.URL_Bukti))}">${ico('receipt_long', 'sm')} Lihat bukti</a>` : '<span class="faint">Tanpa bukti</span>'}</div><div class="row"><button class="btn sm danger" data-v="${esc(k.ID_Transaksi)}" data-a="tolak">${ico('close', 'sm')} Tolak</button><button class="btn primary grow" data-v="${esc(k.ID_Transaksi)}" data-a="terima">${ico('check_circle', 'sm')} Konfirmasi bayar</button></div></div>`;
    let list = rows.filter(k => (!f.periode || k.Periode === f.periode) && (!f.status || k.Status === f.status) && (!f.q || (k.Nama + k.NIS).toLowerCase().indexOf(f.q.toLowerCase()) > -1));
    $('#kv').innerHTML = `<div class="grid g4">${kpiHtml('Penerimaan bulan ini', 'payments', rp(tot), persen(tot, target) + '% dari target ' + rp(target))}${kpiHtml('Menunggu verifikasi', 'hourglass_top', menunggu.length + '<small> transaksi</small>', rp(menunggu.reduce((a, k) => a + Number(k.Nominal), 0)), 'blue')}${kpiHtml('Santri lunas', 'verified', lunas.length + '<small> / ' + bln.length + '</small>', persen(lunas.length, bln.length) + '% kepatuhan')}${kpiHtml('Belum menyelesaikan', 'notifications_active', belum.length + '<small> santri</small>', 'Bulan ' + periodeID(bulanIni()), 'red')}</div>
    <div class="mt">${tabsHtml([['verif', 'Verifikasi bukti (' + menunggu.length + ')'], ['rekap', 'Rekap tagihan']], tab)}</div>
    ${tab === 'verif' ? `<div class="grid g2">${menunggu.length ? menunggu.map(cardBukti).join('') : `<div class="card" style="grid-column:1/-1">${kosong('task_alt', 'Tidak ada bukti transfer yang menunggu.')}</div>`}</div>`
      : `<div class="card"><div class="row wrap"><label class="f"><span class="sr">Periode</span><input class="in" type="month" id="fp" value="${esc(f.periode)}"></label><label class="f grow"><span class="sr">Cari</span><span class="field-icon">${ico('search')}<input class="in" id="fq" placeholder="Cari nama / NIS" value="${esc(f.q)}"></span></label></div>
        <div class="chips mt-s">${[['', 'Semua'], ['Lunas', 'Lunas'], ['Menunggu', 'Menunggu'], ['Belum Bayar', 'Belum bayar'], ['Ditolak', 'Ditolak']].map(c => `<button class="chip ${f.status === c[0] ? 'on' : ''}" data-st="${c[0]}">${c[1]}</button>`).join('')}</div>
        <div class="tbl-wrap mt"><table class="t"><thead><tr><th>Santri</th><th>Periode</th><th>Nominal</th><th>Status</th><th></th></tr></thead><tbody>${list.length ? list.map(k => `<tr><td><div class="nm">${esc(k.Nama)}<small>${esc(k.NIS)} · ${esc(k.Kelas)}</small></div></td><td>${periodeID(k.Periode)}</td><td><b>${rp(k.Nominal)}</b></td><td>${badgeBayar(k.Status)}${k.Catatan ? `<div class="faint" style="font-size:11px">${esc(k.Catatan)}</div>` : ''}</td><td class="right"><div class="row" style="justify-content:flex-end">${urlAman(k.URL_Bukti) ? `<a class="btn sm icon" target="_blank" rel="noopener" href="${esc(urlAman(k.URL_Bukti))}" aria-label="Lihat bukti">${ico('image', 'sm')}</a>` : ''}${(k.Status === 'Belum Bayar' || k.Status === 'Ditolak') ? `<button class="btn sm" data-v="${esc(k.ID_Transaksi)}" data-a="tunai">${ico('payments', 'sm')} Tunai</button>` : ''}${k.Status === 'Lunas' && Number(k.Nominal) > 0 ? `<button class="btn sm icon" data-kw="${esc(k.ID_Transaksi)}" aria-label="Kuitansi">${ico('print', 'sm')}</button>` : ''}</div></td></tr>`).join('') : `<tr><td colspan="5">${kosong('receipt_long', 'Tidak ada tagihan pada filter ini.')}</td></tr>`}</tbody></table></div><p class="faint mt-s" style="font-size:12px">${list.length} tagihan · total ${rp(list.reduce((a, k) => a + Number(k.Nominal), 0))}</p></div>`}`;
  };
  const muat = () => swr('keuangan.list', {}, (d, c, r) => { if (!d) { $('#kv').innerHTML = galat(r && r.message); return; } rows = d.rows; draw(); });
  muat();
  on(v, 'click', '[data-tab]', (e, b) => { tab = b.dataset.tab; draw(); });
  on(v, 'click', '[data-st]', (e, b) => { f.status = b.dataset.st; draw(); });
  on(v, 'change', '#fp', (e, i) => { f.periode = i.value; draw(); });
  on(v, 'input', '#fq', debounce(e => { f.q = e.target.value; draw(); const q = $('#fq'); q.focus(); q.setSelectionRange(q.value.length, q.value.length); }, 200));
  on(v, 'click', '[data-kw]', (e, b) => cetakKuitansi(rows.find(x => x.ID_Transaksi === b.dataset.kw)));
  on(v, 'click', '[data-v]', async (e, b) => {
    const aksi = b.dataset.a, k = rows.find(x => x.ID_Transaksi === b.dataset.v); let catatan = '';
    if (aksi === 'tolak') { catatan = await mintaAlasan(); if (catatan == null) return; }
    if (aksi === 'tunai' && !(await konfirmasi(`Tandai <b>${esc(k.Nama)}</b> (${periodeID(k.Periode)}, ${rp(k.Nominal)}) sebagai dibayar tunai di TU?`, 'Ya, lunas'))) return;
    await tombolSibuk(b, async () => { const r = await api('keuangan.validasi', { id: k.ID_Transaksi, aksi, catatan }); toast(r.message, r.success ? '' : 'error'); if (r.success) { Api.epoch++; muat(); } });
  });
  $('#tb', v).onclick = () => modal({ title: 'Terbitkan tagihan', body: `<div class="form-grid"><label class="f">Periode<input class="in" type="month" id="tp" value="${bulanIni()}"></label><label class="f">Jenis iuran<input class="in" id="tj" value="SPP" maxlength="40"></label><label class="f">Kelas<select class="in" id="tk">${kelasOpt('', 'Semua kelas')}</select></label><label class="f">Nominal khusus (opsional)<span class="hint">Kosongkan untuk memakai tarif per jenjang.</span><input class="in" id="tn" inputmode="numeric" placeholder="mis. 75000"></label><label class="f full">Jatuh tempo<input class="in" type="date" id="tt"></label></div><p class="faint mt-s" style="font-size:12px">Santri penerima beasiswa otomatis lunas. Tagihan yang sudah terbit tidak akan dobel. Wali diberi tahu lewat WhatsApp bila notifikasi aktif.</p>`,
    actions: [{ label: 'Batal' }, { label: 'Terbitkan', cls: 'primary', onClick: async bg => { const r = await api('keuangan.tagihanBuat', { periode: $('#tp', bg).value, jenis: $('#tj', bg).value, kelas: $('#tk', bg).value, nominal: $('#tn', bg).value, jatuhTempo: $('#tt', bg).value }); if (!r.success) { toast(r.message, 'error'); return false; } toast(r.message); Api.epoch++; muat(); } }] });
  $('#exp', v).onclick = () => unduhCSV('keuangan.csv', [['ID', 'NIS', 'Nama', 'Kelas', 'Periode', 'Jenis', 'Nominal', 'Status', 'Tanggal']].concat(rows.map(k => [k.ID_Transaksi, k.NIS, k.Nama, k.Kelas, k.Periode, k.Jenis_Iuran, k.Nominal, k.Status, k.Tanggal])));
  on(v, 'click', '[data-act=muat-ulang]', muat);
  return () => { mati = true; };
}

/* ---------- Materi ---------- */
function pageMateri(v) {
  const staf = Sesi.role !== 'wali'; let rows = [], f = { kelas: '', q: '' }, mati = false;
  v.innerHTML = judul('Kurikulum & Sumber Belajar', 'Pustaka Materi Belajar', staf ? `<button class="btn primary" id="up">${ico('add_circle', 'sm')} Unggah materi</button>` : '') + '<div id="mv">' + skelCards(3) + '</div>';
  const IK = { PDF: 'picture_as_pdf', Video: 'smart_display', Tautan: 'link' };
  const draw = () => {
    if (mati) return; const kls = Array.from(new Set(rows.map(m => m.Kelas || 'Umum')));
    const list = rows.filter(m => (!f.kelas || (m.Kelas || 'Umum') === f.kelas) && (!f.q || (m.Judul + ' ' + m.Kategori + ' ' + m.Pengajar).toLowerCase().indexOf(f.q.toLowerCase()) > -1));
    $('#mv').innerHTML = `<div class="grid g3 mb">${kpiHtml('Total modul', 'auto_stories', rows.length, 'Tersedia di portal')}${kpiHtml('Unduhan', 'download', rows.reduce((a, m) => a + Number(m.Unduhan || 0), 0), 'Seluruh waktu', 'blue')}${kpiHtml('Kelas tercakup', 'school', kls.length, kls.join(', ') || '–')}</div>
    <div class="card"><div class="row wrap"><label class="f grow" style="min-width:200px"><span class="sr">Cari</span><span class="field-icon">${ico('search')}<input class="in" id="mq" placeholder="Cari judul, kategori, ustadz…" value="${esc(f.q)}"></span></label></div><div class="chips scroll mt-s">${[''].concat(kls).map(k => `<button class="chip ${f.kelas === k ? 'on' : ''}" data-k="${esc(k)}">${k || 'Semua materi (' + rows.length + ')'}</button>`).join('')}</div></div>
    <div class="grid g3 mt">${list.length ? list.map(m => `<article class="card col"><div class="row between"><span class="ico kpi" style="display:contents"><span class="ms lg" style="color:var(--primary)">${IK[m.Tipe] || 'description'}</span></span><div class="right"><span class="badge info">${esc(m.Kelas || 'Umum')}</span><div class="faint" style="font-size:11px;margin-top:4px">${esc(m.Tipe)} · ${tglID(m.Tanggal)}</div></div></div>${m.Kategori ? `<div class="faint" style="font:700 10px var(--font-b);letter-spacing:.1em;text-transform:uppercase">${esc(m.Kategori)}</div>` : ''}<h3>${esc(m.Judul)}</h3><p class="sub grow">${esc(m.Deskripsi)}</p><div class="row between faint" style="font-size:12px"><span>${esc(m.Pengajar)}</span><span>${Number(m.Unduhan || 0)} unduhan</span></div><div class="row">${urlAman(m.URL_File) ? `<a class="btn primary grow" target="_blank" rel="noopener" data-dl="${esc(m.ID_Materi)}" href="${esc(urlAman(m.URL_File))}">${ico(m.Tipe === 'Video' ? 'play_circle' : 'download', 'sm')} ${m.Tipe === 'Video' ? 'Tonton' : m.Tipe === 'PDF' ? 'Buka PDF' : 'Buka'}</a>` : ''}${staf && (Sesi.role === 'admin' || m.Pengajar === Sesi.me.nama) ? `<button class="btn icon danger" data-del="${esc(m.ID_Materi)}" aria-label="Hapus">${ico('delete', 'sm')}</button>` : ''}</div></article>`).join('') : `<div class="card" style="grid-column:1/-1">${kosong('auto_stories', 'Belum ada materi.')}</div>`}</div>`;
  };
  const muat = () => swr('materi.list', {}, (d, c, r) => { if (!d) { $('#mv').innerHTML = galat(r && r.message); return; } rows = d.rows; draw(); });
  muat();
  on(v, 'click', '[data-k]', (e, b) => { f.kelas = b.dataset.k; draw(); });
  on(v, 'input', '#mq', debounce(e => { f.q = e.target.value; draw(); const q = $('#mq'); q.focus(); q.setSelectionRange(q.value.length, q.value.length); }, 200));
  on(v, 'click', '[data-dl]', (e, a) => { api('materi.unduh', { id: a.dataset.dl }); });
  on(v, 'click', '[data-del]', async (e, b) => { if (await konfirmasi('Hapus materi ini?', 'Hapus', true)) { const r = await api('materi.hapus', { id: b.dataset.del }); toast(r.message, r.success ? '' : 'error'); if (r.success) muat(); } });
  on(v, 'click', '[data-act=muat-ulang]', muat);
  if (staf) $('#up', v).onclick = () => { let mode = 'pdf';
    modal({ title: 'Unggah materi baru', wide: true, body: `<div class="form-grid"><label class="f full">Judul<input class="in" id="mj" maxlength="120"></label><label class="f">Kelas<select class="in" id="mk"><option value="Umum">Umum (semua kelas)</option>${Meta().kelas.map(k => `<option>${esc(k)}</option>`).join('')}</select></label><label class="f">Kategori<input class="in" id="mc" placeholder="mis. Fiqih Ibadah" maxlength="40"></label><div class="full"><div class="seg" id="mm"><button type="button" data-m="pdf" class="on">Berkas PDF</button><button type="button" data-m="link">Tautan / video</button></div></div><label class="f full" id="mpdf">Berkas PDF (maks 6 MB)<input class="in" type="file" id="mf" accept="application/pdf"></label><label class="f full hide" id="mlink">Tautan (https://…)<input class="in" id="mu" placeholder="https://youtube.com/…"></label><label class="f full">Deskripsi singkat<textarea class="in" id="md" maxlength="300"></textarea></label></div>`,
      onOpen: bg => { on(bg, 'click', '#mm button', (e, b) => { mode = b.dataset.m; $$('#mm button', bg).forEach(x => x.classList.toggle('on', x === b)); $('#mpdf', bg).classList.toggle('hide', mode !== 'pdf'); $('#mlink', bg).classList.toggle('hide', mode !== 'link'); }); },
      actions: [{ label: 'Batal' }, { label: 'Unggah', cls: 'primary', onClick: async bg => { const d = { Judul: $('#mj', bg).value, Kelas: $('#mk', bg).value, Kategori: $('#mc', bg).value, Deskripsi: $('#md', bg).value };
        try { if (mode === 'pdf') { const fl = $('#mf', bg).files[0]; if (!fl) { toast('Pilih berkas PDF.', 'warn'); return false; } if (fl.type !== 'application/pdf' || fl.size > 6 * 1048576) { toast('Berkas harus PDF dan maksimal 6 MB.', 'error'); return false; } d.base64 = await berkasKeBase64(fl); d.mime = fl.type; } else d.URL_File = $('#mu', bg).value.trim(); } catch (e) { toast(e.message, 'error'); return false; }
        const r = await api('materi.save', d, { timeout: 120000 }); if (!r.success) { toast(r.message, 'error'); return false; } toast(r.message); Api.epoch++; muat(); } }] }); };
  return () => { mati = true; };
}

/* ---------- Laporan ---------- */
function pageLaporan(v) {
  let bulan = bulanIni(), kelas = '', rows = [], mati = false;
  v.innerHTML = judul('Akademik', 'Laporan Bulanan', `<button class="btn" id="csv">${ico('download', 'sm')} Ekspor CSV</button><button class="btn" onclick="window.print()">${ico('print', 'sm')} Cetak</button>`) + `<div class="card no-print"><div class="row wrap"><label class="f"><span class="sr">Bulan</span><input class="in" type="month" id="lb" value="${bulan}"></label><label class="f"><span class="sr">Kelas</span><select class="in" id="lk">${kelasOpt('', 'Semua kelas')}</select></label></div></div><div id="lv" class="mt"></div>`;
  const draw = () => { if (mati) return; const tot = rows.reduce((a, r) => ({ H: a.H + r.H, I: a.I + r.I, S: a.S + r.S, A: a.A + r.A }), { H: 0, I: 0, S: 0, A: 0 }), n = tot.H + tot.I + tot.S + tot.A;
    $('#lv').innerHTML = `<div class="grid g4">${kpiHtml('Rata-rata kehadiran', 'how_to_reg', persen(tot.H, n) + '%', periodeID(bulan))}${kpiHtml('Izin + sakit', 'medical_services', tot.I + tot.S, '', 'blue')}${kpiHtml('Alfa', 'warning', tot.A, 'kejadian', 'red')}${kpiHtml('Total setoran', 'menu_book', rows.reduce((a, r) => a + r.Setoran, 0), 'bulan ini')}</div>
    <div class="card mt"><h3>Rekap per santri — ${periodeID(bulan)}${kelas ? ' · ' + esc(kelas) : ''}</h3><div class="tbl-wrap mt"><table class="t"><thead><tr><th>Santri</th><th>Kelas</th><th>H</th><th>I</th><th>S</th><th>A</th><th>% Hadir</th><th>Setoran</th></tr></thead><tbody>${rows.length ? rows.map(r => `<tr><td><div class="nm">${esc(r.Nama)}<small>${esc(r.NIS)}</small></div></td><td>${esc(r.Kelas)}</td><td>${r.H}</td><td>${r.I}</td><td>${r.S}</td><td>${r.A}</td><td><span class="badge ${r.Persen >= 85 ? 'ok' : r.Persen >= 70 ? 'warn' : 'bad'}">${r.Persen}%</span></td><td>${r.Setoran}</td></tr>`).join('') : `<tr><td colspan="8">${kosong('bar_chart', 'Tidak ada data.')}</td></tr>`}</tbody></table></div></div>`; };
  const muat = async () => { $('#lv').innerHTML = skelCards(2); const r = await api('laporan.bulanan', { bulan, kelas }); if (mati) return; if (!r.success) { $('#lv').innerHTML = galat(r.message); return; } rows = r.data.rows; draw(); };
  muat();
  on(v, 'change', '#lb', (e, i) => { if (i.value) { bulan = i.value; muat(); } }); on(v, 'change', '#lk', (e, s) => { kelas = s.value; muat(); });
  on(v, 'click', '#csv', () => unduhCSV('laporan-' + bulan + '.csv', [['NIS', 'Nama', 'Kelas', 'Hadir', 'Izin', 'Sakit', 'Alfa', 'Persen hadir', 'Setoran']].concat(rows.map(r => [r.NIS, r.Nama, r.Kelas, r.H, r.I, r.S, r.A, r.Persen, r.Setoran]))));
  on(v, 'click', '[data-act=muat-ulang]', muat);
  return () => { mati = true; };
}

/* ---------- WhatsApp & Notifikasi ---------- */
function pageNotifikasi(v) {
  let tab = 'blast', cfg = null, mati = false, loop = false;
  v.innerHTML = judul('Administrasi', 'WhatsApp & Notifikasi') + '<div id="nt"></div>';
  const tabs = () => tabsHtml([['blast', 'Blast pesan'], ['antrean', 'Antrean & log'], ['konfig', 'Konfigurasi']], tab);
  const render = async () => { if (mati) return; $('#nt').innerHTML = tabs() + '<div id="nb">' + skelCards(1) + '</div>'; if (tab === 'konfig') await tabKonfig(); else if (tab === 'antrean') await tabAntrean(); else await tabBlast(); };
  const muatCfg = async () => { const r = await api('notif.config'); if (r.success) cfg = r.data; return r; };

  async function tabKonfig() {
    const r = await muatCfg(); if (mati) return; if (!r.success) { $('#nb').innerHTML = galat(r.message); return; }
    const c = cfg;
    $('#nb').innerHTML = `<div class="notice mb">${ico('info')}<span>Semua pesan dikirim lewat <b>antrean</b> (trigger tiap menit) sehingga penyimpanan presensi/tagihan tetap instan. Token Fonnte disimpan <b>hanya di server</b> dan tidak pernah dikirim ke browser.</span></div>
    <div class="grid g2"><form class="card col gap-lg" id="cf"><h3>Kanal & token</h3>
      <label class="row between"><span><b>WhatsApp (Fonnte)</b><br><span class="sub">Saklar utama kirim WA</span></span><input type="checkbox" class="switch" id="cwa" ${c.waAktif ? 'checked' : ''}></label>
      <label class="row between"><span><b>Email</b><br><span class="sub">Sisa kuota harian: ${c.kuotaEmail}</span></span><input type="checkbox" class="switch" id="cem" ${c.emailAktif ? 'checked' : ''}></label>
      <label class="f">Token Fonnte<span class="hint">${c.tokenAda ? 'Tersimpan: ' + esc(c.tokenSamar) + ' — isi hanya untuk mengganti.' : 'Belum diisi. Ambil dari dashboard Fonnte.'}</span><input class="in" id="ctk" type="password" autocomplete="off" placeholder="${c.tokenAda ? '••••••••' : 'tempel token'}"></label>
      ${c.tokenAda ? `<label class="chk"><input type="checkbox" id="chapus"><span>Hapus token tersimpan</span></label>` : ''}
      <div class="form-grid"><label class="f">Ukuran batch blast<select class="in" id="cb">${[10, 20, 50].map(n => `<option ${String(n) === String(c.batchDefault) ? 'selected' : ''}>${n}</option>`).join('')}</select></label><label class="f">Jeda antarpesan (detik)<input class="in" id="cj" value="${esc(c.jeda)}" placeholder="5 atau 3-8"></label>
      <label class="f">WA admin/TU (pemberitahuan internal)<input class="in" id="cah" inputmode="tel" value="${esc(c.adminHp)}" placeholder="08…"></label><label class="f">Email admin/TU<input class="in" id="cae" type="email" value="${esc(c.adminEmail)}"></label>
      <label class="f">Nama pengirim email<input class="in" id="cnp" value="${esc(c.namaPengirim)}"></label><label class="f">URL aplikasi (untuk {link})<input class="in" id="cau" value="${esc(c.appUrl)}" placeholder="https://username.github.io/repo/"></label></div>
      <label class="chk"><input type="checkbox" id="cdo" ${c.deteksiOtomatis ? 'checked' : ''}><span>Deteksi nomor WA otomatis (kontak baru)</span></label>
      <div class="row wrap"><button class="btn primary" type="submit">${ico('save', 'sm')} Simpan konfigurasi</button><button class="btn" type="button" id="cdv">${ico('smartphone', 'sm')} Cek perangkat</button><button class="btn" type="button" id="cts">${ico('send', 'sm')} Tes kirim</button></div><div id="cinfo"></div></form>
      <div class="card"><h3>Matriks kejadian × kanal</h3><p class="sub">Pilih kejadian mana yang mengirim notifikasi dan ubah templatnya.</p><div class="col mt">${c.matriks.map((m, i) => `<div class="inset" style="padding:12px" data-mx="${i}"><div class="row between wrap"><b>${esc(m.label)}</b><div class="row"><label class="chk"><input type="checkbox" data-w ${m.wa ? 'checked' : ''}><span>WA</span></label><label class="chk"><input type="checkbox" data-e ${m.email ? 'checked' : ''}><span>Email</span></label></div></div><details class="mt-s"><summary style="cursor:pointer;color:var(--secondary)">Ubah templat</summary><label class="f mt-s">Subjek email<input class="in sm" data-sj value="${esc(m.subjek)}"></label><label class="f mt-s">Pesan<textarea class="in sm" data-ps rows="5">${esc(m.pesan)}</textarea></label><button type="button" class="btn sm mt-s" data-reset="${i}">Kembalikan bawaan</button></details></div>`).join('')}</div>
      <p class="faint mt-s" style="font-size:12px">Variabel: {nama} {santri} {kelas} {institusi} {link} dan variabel khusus tiap kejadian (mis. {periode}, {jumlah}).</p></div></div>`;
    on($('#nb'), 'click', '[data-reset]', (e, b) => { const m = c.matriks[+b.dataset.reset], box = b.closest('[data-mx]'); $('[data-sj]', box).value = m.subjekDefault; $('[data-ps]', box).value = m.pesanDefault; });
    $('#cdv').onclick = async () => { const r = await api('wa.device'); $('#cinfo').innerHTML = r.success ? `<div class="notice info mt">${ico('smartphone')}<span>Perangkat <b>${esc(r.data.nomor)}</b> · ${esc(r.data.status)} · paket ${esc(r.data.paket)} · kuota ${esc(r.data.kuota)}</span></div>` : `<div class="notice bad mt">${ico('error')}<span>${esc(r.message)}</span></div>`; };
    $('#cts').onclick = () => modal({ title: 'Tes kirim WhatsApp', body: '<label class="f">Nomor tujuan<input class="in" id="tn" inputmode="tel" placeholder="08…"></label>', actions: [{ label: 'Batal' }, { label: 'Kirim tes', cls: 'primary', onClick: async bg => { const r = await api('wa.test', { nomor: $('#tn', bg).value }); toast(r.message, r.success ? '' : 'error'); if (!r.success) return false; } }] });
    $('#cf').onsubmit = async e => { e.preventDefault(); await tombolSibuk($('#cf button[type=submit]'), async () => {
      const mx = $$('[data-mx]', $('#nb')).map(box => ({ kode: c.matriks[+box.dataset.mx].kode, wa: $('[data-w]', box).checked, email: $('[data-e]', box).checked, subjek: $('[data-sj]', box).value, pesan: $('[data-ps]', box).value }));
      const body = { waAktif: $('#cwa').checked, emailAktif: $('#cem').checked, token: $('#chapus') && $('#chapus').checked ? '__HAPUS__' : $('#ctk').value, batchDefault: $('#cb').value, jeda: $('#cj').value, adminHp: $('#cah').value, adminEmail: $('#cae').value, namaPengirim: $('#cnp').value, appUrl: $('#cau').value, deteksiOtomatis: $('#cdo').checked, matriks: mx };
      const r = await api('notif.configSave', body); toast(r.message, r.success ? '' : 'error'); if (r.success) { tab = 'konfig'; render(); } }); };
  }

  async function tabAntrean() {
    const r = await api('notif.queue', {}); if (mati) return; if (!r.success) { $('#nb').innerHTML = galat(r.message); return; }
    const q = r.data, B = { Terkirim: 'ok', Antri: 'info', Gagal: 'bad', Batal: '' };
    $('#nb').innerHTML = `<div class="grid g4">${kpiHtml('Antri', 'schedule', q.ringkas.Antri, 'menunggu trigger', 'blue')}${kpiHtml('Terkirim', 'done_all', q.ringkas.Terkirim, '300 terakhir')}${kpiHtml('Gagal', 'error', q.ringkas.Gagal, 'bisa dikirim ulang', 'red')}${kpiHtml('Dibatalkan', 'block', q.ringkas.Batal, '')}</div>
    <div class="card mt"><div class="row between wrap"><h3>Log pengiriman</h3><div class="row"><button class="btn sm" id="pn">${ico('play_arrow', 'sm')} Proses sekarang</button><button class="btn sm" id="rt">${ico('replay', 'sm')} Kirim ulang yang gagal</button></div></div><div class="tbl-wrap mt"><table class="t"><thead><tr><th>Waktu</th><th>Kanal</th><th>Tujuan</th><th>Kejadian</th><th>Status</th><th>Respons</th></tr></thead><tbody>${q.rows.length ? q.rows.map(x => `<tr><td class="mono" style="font-size:12px">${esc(String(x.DibuatPada).replace('T', ' ').slice(5, 16))}</td><td>${esc(x.Kanal)}</td><td><div class="nm">${esc(x.NamaPenerima || '-')}<small class="mono">${esc(x.Tujuan)}</small></div></td><td>${esc(x.Event)}</td><td><span class="badge ${B[x.Status]}">${esc(x.Status)}</span></td><td class="faint" style="font-size:12px">${esc(x.Respon)}</td></tr>`).join('') : `<tr><td colspan="6">${kosong('forum', 'Belum ada pesan di antrean.')}</td></tr>`}</tbody></table></div></div>`;
    $('#pn').onclick = async e => { await tombolSibuk(e.currentTarget, async () => { const r = await api('notif.processNow', {}, { timeout: 120000 }); toast(r.message, r.success ? '' : 'error'); render(); }); };
    $('#rt').onclick = async e => { await tombolSibuk(e.currentTarget, async () => { const r = await api('notif.retry'); toast(r.message, r.success ? '' : 'error'); render(); }); };
  }

  async function tabBlast() {
    if (!cfg) await muatCfg(); if (mati) return;
    const bl = await api('wa.blastList'); if (mati) return;
    let seg = 'Wali', kls = '', aud = null, batch = Number((cfg && cfg.batchDefault) || 20), jeda = (cfg && cfg.jeda) || '5';
    const info = cfg && cfg.tokenAda && cfg.waAktif ? '' : `<div class="notice mb">${ico('warning')}<span>WhatsApp belum aktif. Isi token dan aktifkan di tab <b>Konfigurasi</b> sebelum blast.</span></div>`;
    $('#nb').innerHTML = `${info}<div class="grid g-main2"><div class="card col gap-lg"><h3>Buat blast baru</h3>
      <div class="form-grid"><label class="f">Judul blast<input class="in" id="bj" maxlength="80" placeholder="mis. Pengumuman ujian tasmi'"></label><label class="f">Sasaran<select class="in" id="bs"><option value="Wali">Wali santri</option><option value="Asatidz">Asatidz</option><option value="">Semua kontak</option></select></label><label class="f">Kelas (untuk wali)<select class="in" id="bk">${kelasOpt('', 'Semua kelas')}</select></label><label class="f">Ukuran batch<div class="seg fill" id="bb">${[10, 20, 50].map(n => `<button type="button" data-b="${n}" class="${n === batch ? 'on' : ''}">${n}</button>`).join('')}</div></label></div>
      <div id="aud" class="inset" style="padding:12px 14px">Memuat sasaran…</div>
      <label class="f">Pesan<span class="hint">Variabel: {nama} {santri} {kelas} {institusi}</span><textarea class="in" id="bp" rows="6" maxlength="900" placeholder="Assalamu'alaikum {nama}, …"></textarea></label>
      <div><div class="sub" style="font-weight:600;margin-bottom:6px">Pratinjau</div><div class="bubble" id="bv">Assalamu'alaikum…</div></div>
      <label class="f">Jeda antarpesan (detik)<input class="in" id="bje" value="${esc(jeda)}" placeholder="5 atau 3-8"></label>
      <button class="btn primary" id="bgo">${ico('send', 'sm')} Mulai blast</button></div>
      <div class="card"><div class="row between"><h3>Riwayat blast</h3><button class="btn sm" id="bref">${ico('refresh', 'sm')}</button></div><div class="col mt" id="bl">${blastList(bl.data ? bl.data.rows : [])}</div></div></div>`;
    const muatAud = async () => { const r = await api('wa.audience', { segmen: seg, kelas: seg === 'Wali' ? kls : '' }); if (mati) return; aud = r.success ? r.data : null; const a = $('#aud'); if (!a) return; a.innerHTML = r.success ? `<b>${aud.ringkas.valid}</b> penerima valid · ${aud.ringkas.ganda} ganda · ${aud.ringkas.tidakValid} nomor tidak valid · ${aud.ringkas.optOut} opt-out · <span class="faint">${aud.ringkas.tidakTerdaftarWA} diketahui tidak terdaftar WA</span>${aud.ringkas.total === 0 ? '<br><span class="faint">Kontak kosong — buka menu CRM dan tekan “Sinkronkan”.</span>' : ''}` : esc(r.message); };
    muatAud();
    on($('#nb'), 'change', '#bs', (e, s) => { seg = s.value; muatAud(); }); on($('#nb'), 'change', '#bk', (e, s) => { kls = s.value; muatAud(); });
    on($('#nb'), 'click', '#bb button', (e, b) => { batch = Number(b.dataset.b); $$('#bb button').forEach(x => x.classList.toggle('on', x === b)); });
    on($('#nb'), 'input', '#bp', (e, t) => { $('#bv').textContent = t.value.replace(/\{nama\}/g, 'Bpk. Contoh').replace(/\{santri\}/g, 'Ahmad Fulan').replace(/\{kelas\}/g, 'Ula 2').replace(/\{institusi\}/g, (Sesi.meta && Sesi.meta.madrasah) || 'MDT') || "Assalamu'alaikum…"; });
    $('#bref').onclick = refresh;
    async function refresh() { const r = await api('wa.blastList'); if (mati || !$('#bl')) return; $('#bl').innerHTML = blastList(r.data ? r.data.rows : []); return r.data ? r.data.rows : []; }
    async function jalankan(id) { if (loop) return; loop = true; try { while (!mati) { const r = await api('wa.blastProcess', { blastId: id }, { timeout: 120000 }); if (!r.success || !r.data.blast || r.data.blast.Status !== 'Berjalan') break; await refresh(); await sleep(1500); } } finally { loop = false; if (!mati) refresh(); } }
    on($('#nb'), 'click', '[data-lanjut]', (e, b) => jalankan(b.dataset.lanjut));
    on($('#nb'), 'click', '[data-stop]', async (e, b) => { if (await konfirmasi('Hentikan blast ini? Pesan yang belum terkirim akan dibatalkan.', 'Hentikan', true)) { const r = await api('wa.blastStop', { blastId: b.dataset.stop }); toast(r.message, r.success ? '' : 'error'); refresh(); } });
    $('#bgo').onclick = async e => {
      if (!aud) return toast('Sasaran belum termuat.', 'warn'); const pesan = $('#bp').value.trim(); if (!pesan) return toast('Isi pesan blast.', 'warn');
      const pen = aud.rows.filter(x => x.valid && !x.ganda && !x.optOut && x.statusWA !== 'Tidak Terdaftar').map(x => ({ hp: x.hp, nama: x.nama, santri: x.santri, kelas: x.kelas }));
      if (!pen.length) return toast('Tidak ada penerima valid.', 'warn');
      if (!(await konfirmasi(`Kirim ke <b>${pen.length}</b> penerima dalam batch ${batch} dengan jeda ${esc($('#bje').value)} detik?`, 'Mulai blast'))) return;
      await tombolSibuk(e.currentTarget, async () => { const r = await api('wa.blastCreate', { judul: $('#bj').value, pesan, penerima: pen, ukuranBatch: batch, jeda: $('#bje').value, sasaran: seg + (kls ? ' ' + kls : '') }, { timeout: 120000 }); toast(r.message, r.success ? '' : 'error'); if (r.success) { await refresh(); jalankan(r.data.blastId); } }); };
    const rr = bl.data ? bl.data.rows.find(x => x.Status === 'Berjalan') : null; if (rr) jalankan(rr.BlastID);
  }
  const blastList = rows => rows.length ? rows.map(b => `<div class="inset" style="padding:12px 14px"><div class="row between"><b>${esc(b.Judul)}</b><span class="badge ${b.Status === 'Selesai' ? 'ok' : b.Status === 'Berjalan' ? 'info' : 'warn'}">${esc(b.Status)}</span></div><div class="sub">${esc(b.Sasaran)} · ${esc(String(b.Tanggal).replace('T', ' ').slice(0, 16))}</div><div class="bar mt-s"><i style="width:${b.persen}%"></i></div><div class="row between mt-s" style="font-size:12px"><span>${b.Terkirim} terkirim · ${b.Gagal} gagal · ${b.sisa} sisa</span><span class="row">${b.Status === 'Berjalan' ? `<button class="btn sm" data-lanjut="${esc(b.BlastID)}">Proses</button><button class="btn sm danger" data-stop="${esc(b.BlastID)}">Stop</button>` : ''}</span></div></div>`).join('') : kosong('forum', 'Belum ada blast.');
  on(v, 'click', '[data-tab]', (e, b) => { tab = b.dataset.tab; render(); });
  on(v, 'click', '[data-act=muat-ulang]', render);
  render();
  return () => { mati = true; };
}

/* ---------- CRM Kontak ---------- */
function pageCRM(v) {
  let f = { cari: '', segmen: '', statusWA: '', optOut: false, halaman: 1 }, d = null, sel = new Set(), mati = false;
  v.innerHTML = judul('Administrasi', 'CRM Kontak', `<button class="btn primary" id="sync">${ico('sync', 'sm')} Sinkronkan</button><button class="btn" id="cek">${ico('verified', 'sm')} Cek nomor WA</button>`) + '<div id="cv">' + skelCards(2) + '</div>';
  const muat = async () => { const [s, l] = await Promise.all([api('crm.stats'), api('crm.list', f)]); if (mati) return; if (!l.success) { $('#cv').innerHTML = galat(l.message); return; } d = l.data; const st = s.data || {};
    const pages = Math.max(1, Math.ceil(d.total / d.per));
    $('#cv').innerHTML = `<div class="grid g4">${kpiHtml('Total kontak', 'contacts', st.total || 0, 'Wali + asatidz')}${kpiHtml('Nomor WA valid', 'chat', st.wa || 0, (st.terdaftarWA || 0) + ' terdaftar di WA', 'blue')}${kpiHtml('Belum dicek', 'help', st.belumCek || 0, 'butuh deteksi WA', 'amber')}${kpiHtml('Opt-out', 'unsubscribe', st.optOut || 0, (st.duplikat || 0) + ' nomor ganda', 'red')}</div>
    <div class="card mt"><div class="row wrap"><label class="f grow" style="min-width:200px"><span class="sr">Cari</span><span class="field-icon">${ico('search')}<input class="in" id="cq" placeholder="Cari nama, email, nomor…" value="${esc(f.cari)}"></span></label><select class="in" id="cs" style="max-width:170px"><option value="">Semua segmen</option>${Object.keys(d.facet).map(k => `<option ${f.segmen === k ? 'selected' : ''}>${esc(k)}</option>`).join('')}</select><select class="in" id="cw" style="max-width:190px"><option value="">Status WA: semua</option>${['Terdaftar', 'Tidak Terdaftar', 'Belum'].map(k => `<option ${f.statusWA === k ? 'selected' : ''}>${k}</option>`).join('')}</select><label class="chk"><input type="checkbox" id="co" ${f.optOut ? 'checked' : ''}><span>Opt-out saja</span></label></div>
      ${sel.size ? `<div class="row wrap mt-s inset" style="padding:8px 12px"><b>${sel.size} dipilih</b><button class="btn sm" data-bulk="optout">Opt-out</button><button class="btn sm" data-bulk="optin">Batalkan opt-out</button><button class="btn sm" data-bulk="tag">Beri tag…</button></div>` : ''}
      <div class="tbl-wrap mt"><table class="t"><thead><tr><th style="width:36px"></th><th>Nama</th><th>Segmen</th><th>WhatsApp</th><th>Email</th><th>Terakhir dihubungi</th><th></th></tr></thead><tbody>${d.rows.length ? d.rows.map(k => `<tr><td><input type="checkbox" data-s="${esc(k.KontakID)}" ${sel.has(k.KontakID) ? 'checked' : ''} aria-label="Pilih ${esc(k.Nama)}"></td><td><div class="nm">${esc(k.Nama || '-')}<small>${esc(k.Tag)}</small></div></td><td><span class="badge info">${esc(k.Segmen)}</span></td><td><span class="mono">${esc(k.NoWA || '-')}</span> ${k.StatusWA ? `<span class="badge ${k.StatusWA === 'Terdaftar' ? 'ok' : 'bad'}">${esc(k.StatusWA)}</span>` : ''}${k.OptOut === 'YA' ? ' <span class="badge warn">opt-out</span>' : ''}</td><td>${esc(k.Email || '-')}</td><td class="faint">${k.TerakhirDihubungi ? tglID(k.TerakhirDihubungi) : '-'} · ${k.JumlahPesan}×</td><td class="right"><button class="btn sm icon" data-ed="${esc(k.KontakID)}" aria-label="Ubah">${ico('edit', 'sm')}</button></td></tr>`).join('') : `<tr><td colspan="7">${kosong('contacts', 'Belum ada kontak. Tekan “Sinkronkan”.')}</td></tr>`}</tbody></table></div>
      <div class="pager"><button class="btn sm icon" data-p="-1" ${f.halaman <= 1 ? 'disabled' : ''} aria-label="Sebelumnya">${ico('chevron_left', 'sm')}</button><span>Hal ${f.halaman} / ${pages} · ${d.total} kontak</span><button class="btn sm icon" data-p="1" ${f.halaman >= pages ? 'disabled' : ''} aria-label="Berikutnya">${ico('chevron_right', 'sm')}</button></div></div>`; };
  muat();
  on(v, 'input', '#cq', debounce(e => { f.cari = e.target.value; f.halaman = 1; muat().then(() => { const q = $('#cq'); if (q) { q.focus(); q.setSelectionRange(q.value.length, q.value.length); } }); }, 350));
  on(v, 'change', '#cs', (e, s) => { f.segmen = s.value; f.halaman = 1; muat(); }); on(v, 'change', '#cw', (e, s) => { f.statusWA = s.value; f.halaman = 1; muat(); }); on(v, 'change', '#co', (e, c) => { f.optOut = c.checked; f.halaman = 1; muat(); });
  on(v, 'click', '[data-p]', (e, b) => { f.halaman += Number(b.dataset.p); muat(); });
  on(v, 'change', '[data-s]', (e, c) => { c.checked ? sel.add(c.dataset.s) : sel.delete(c.dataset.s); muat(); });
  on(v, 'click', '[data-bulk]', async (e, b) => { let nilai = ''; if (b.dataset.bulk === 'tag') { nilai = prompt('Tag untuk kontak terpilih:'); if (!nilai) return; } const r = await api('crm.bulk', { ids: Array.from(sel), aksi: b.dataset.bulk, nilai }); toast(r.message, r.success ? '' : 'error'); if (r.success) { sel.clear(); muat(); } });
  on(v, 'click', '[data-ed]', (e, b) => { const k = d.rows.find(x => x.KontakID === b.dataset.ed);
    modal({ title: 'Kontak: ' + (k.Nama || '-'), body: `<div class="col"><div class="sub">${esc(k.Segmen)} · ${esc(k.NoWA || 'tanpa nomor')} · ${esc(k.Email || 'tanpa email')}</div><label class="f">Tag (pisahkan koma)<input class="in" id="kt" value="${esc(k.Tag)}"></label><label class="f">Catatan<textarea class="in" id="kc">${esc(k.Catatan)}</textarea></label><label class="chk"><input type="checkbox" id="ko" ${k.OptOut === 'YA' ? 'checked' : ''}><span>Opt-out (tidak menerima blast)</span></label><div class="sep"></div><label class="f">Catat interaksi manual<select class="in" id="ki"><option>Telepon</option><option>WA Manual</option><option>Kunjungan</option><option>Catatan</option></select></label><textarea class="in" id="kr" placeholder="Ringkasan interaksi (opsional)"></textarea></div>`,
      actions: [{ label: 'Batal' }, { label: 'Simpan', cls: 'primary', onClick: async bg => { const r = await api('crm.save', { kontakId: k.KontakID, tag: $('#kt', bg).value, catatan: $('#kc', bg).value, optOut: $('#ko', bg).checked }); if (!r.success) { toast(r.message, 'error'); return false; } const t = $('#kr', bg).value.trim(); if (t) await api('crm.interaksi', { kontakId: k.KontakID, kanal: $('#ki', bg).value, ringkasan: t }); toast('Tersimpan.'); muat(); } }] }); });
  $('#sync', v).onclick = async e => { await tombolSibuk(e.currentTarget, async () => { const r = await api('crm.sync'); toast(r.success ? `Sinkron: ${r.data.ditambah} baru, ${r.data.diperbarui} diperbarui.` : r.message, r.success ? '' : 'error'); muat(); }); };
  $('#cek', v).onclick = async e => { await tombolSibuk(e.currentTarget, async () => { const r0 = await api('crm.list', { statusWA: 'Belum', halaman: 1 }); const nomor = (r0.data ? r0.data.rows : []).map(k => k.NoWA).filter(Boolean).slice(0, 50); if (!nomor.length) return toast('Semua nomor sudah dicek.'); const r = await api('wa.validate', { nomor }); toast(r.message, r.success ? '' : 'error'); muat(); }); };
  on(v, 'click', '[data-act=muat-ulang]', muat);
  return () => { mati = true; };
}

/* ---------- Pengguna ---------- */
function pagePengguna(v) {
  let rows = [], mati = false; const R = { admin: 'Admin TU', ustadz: 'Ustadz', wali: 'Wali' };
  v.innerHTML = judul('Administrasi', 'Manajemen Pengguna', `<button class="btn primary" id="add">${ico('person_add', 'sm')} Tambah pengguna</button>`) + '<div id="pu">' + skelCards(1) + '</div>';
  const form = u => { u = u || {}; return `<div class="form-grid"><label class="f">Peran<select class="in" id="ur" ${u.UserID ? 'disabled' : ''}>${Object.keys(R).map(k => `<option value="${k}" ${u.Role === k ? 'selected' : ''}>${R[k]}</option>`).join('')}</select></label><label class="f">Username / ID masuk<input class="in" id="uu" value="${esc(u.Username || '')}" maxlength="40" autocapitalize="none"></label><label class="f">Nama lengkap<input class="in" id="un" value="${esc(u.Nama || '')}" maxlength="80"></label><label class="f">No. HP<input class="in" id="uh" value="${esc(u.HP || '')}" inputmode="tel"></label><label class="f">Email<input class="in" id="ue" type="email" value="${esc(u.Email || '')}"></label><label class="f">Kelas (ustadz)<select class="in" id="uk">${kelasOpt(u.Kelas, '—')}</select></label><label class="f full">NIS santri tertaut (wali; pisahkan koma)<input class="in" id="us" value="${esc(u.Santri || '')}" placeholder="2026001, 2026002"></label><label class="f">Status<select class="in" id="ut"><option ${u.Status !== 'Nonaktif' ? 'selected' : ''}>Aktif</option><option ${u.Status === 'Nonaktif' ? 'selected' : ''}>Nonaktif</option></select></label></div>`; };
  const baca = (bg, u) => ({ UserID: u ? u.UserID : undefined, Role: u ? u.Role : $('#ur', bg).value, Username: $('#uu', bg).value, Nama: $('#un', bg).value, HP: $('#uh', bg).value, Email: $('#ue', bg).value, Kelas: $('#uk', bg).value, Santri: $('#us', bg).value, Status: $('#ut', bg).value });
  const draw = () => { if (mati) return; $('#pu').innerHTML = `<div class="card"><div class="tbl-wrap"><table class="t"><thead><tr><th>Pengguna</th><th>Peran</th><th>Tertaut</th><th>Status</th><th></th></tr></thead><tbody>${rows.length ? rows.map(u => `<tr><td><div class="row">${av(u.Nama)}<div class="nm">${esc(u.Nama)}<small class="mono">${esc(u.Username)}</small></div></div></td><td><span class="badge info">${R[u.Role]}</span></td><td class="faint">${esc(u.Santri || u.Kelas || '-')}</td><td><span class="badge ${u.Status === 'Aktif' ? 'ok' : 'bad'}">${esc(u.Status)}</span></td><td class="right"><button class="btn sm icon" data-ed="${esc(u.UserID)}" aria-label="Ubah">${ico('edit', 'sm')}</button> <button class="btn sm icon" data-rs="${esc(u.UserID)}" aria-label="Reset sandi">${ico('key', 'sm')}</button></td></tr>`).join('') : `<tr><td colspan="5">${kosong('manage_accounts', 'Belum ada pengguna.')}</td></tr>`}</tbody></table></div></div>`; };
  const muat = () => swr('pengguna.list', {}, (d, c, r) => { if (!d) { $('#pu').innerHTML = galat(r && r.message); return; } rows = d.rows; draw(); }, { noCache: true }); muat();
  $('#add', v).onclick = () => modal({ title: 'Tambah pengguna', wide: true, body: form(), actions: [{ label: 'Batal' }, { label: 'Buat akun', cls: 'primary', onClick: async bg => { const r = await api('pengguna.save', baca(bg)); if (!r.success) { toast(r.message, 'error'); return false; } toast(r.message); tampilkanKredensial('Akun baru', [{ wali: $('#un', bg).value, username: r.data.username, sandi: r.data.sandi }]); muat(); } }] });
  on(v, 'click', '[data-ed]', (e, b) => { const u = rows.find(x => x.UserID === b.dataset.ed); modal({ title: 'Ubah pengguna', wide: true, body: form(u), actions: [{ label: 'Batal' }, { label: 'Simpan', cls: 'primary', onClick: async bg => { const r = await api('pengguna.save', baca(bg, u)); if (!r.success) { toast(r.message, 'error'); return false; } toast(r.message); muat(); } }] }); });
  on(v, 'click', '[data-rs]', async (e, b) => { const u = rows.find(x => x.UserID === b.dataset.rs); if (!(await konfirmasi(`Reset sandi <b>${esc(u.Nama)}</b>? Sandi lama tidak berlaku dan semua sesinya dikeluarkan.`, 'Reset sandi', true))) return; const r = await api('pengguna.resetSandi', { UserID: u.UserID }); if (!r.success) return toast(r.message, 'error'); tampilkanKredensial('Sandi baru', [{ wali: u.Nama, username: r.data.username, sandi: r.data.sandi }]); });
  on(v, 'click', '[data-act=muat-ulang]', muat);
  return () => { mati = true; };
}

/* ---------- Berita & Agenda ---------- */
function pageBerita(v) {
  let rows = [], mati = false;
  v.innerHTML = judul('Administrasi', 'Berita & Agenda', `<button class="btn primary" id="add">${ico('add', 'sm')} Tulis pengumuman</button>`) + '<div id="bv">' + skelCards(1) + '</div>';
  const form = b => { b = b || {}; return `<div class="form-grid"><label class="f full">Judul<input class="in" id="bj" value="${esc(b.Judul || '')}" maxlength="140"></label><label class="f">Tanggal<input class="in" type="date" id="bt" value="${esc(b.Tanggal || hariIni())}"></label><label class="f">Kategori<input class="in" id="bc" value="${esc(b.Kategori || 'Pengumuman')}" maxlength="30"></label><label class="f full">Ringkasan<textarea class="in" id="br" maxlength="400">${esc(b.Ringkasan || '')}</textarea></label><label class="f">Lokasi<input class="in" id="bl" value="${esc(b.Lokasi || '')}" maxlength="100"></label><label class="f">Status<select class="in" id="bs"><option ${b.Status !== 'Draft' ? 'selected' : ''}>Terbit</option><option ${b.Status === 'Draft' ? 'selected' : ''}>Draft</option></select></label></div>`; };
  const baca = (bg, b) => ({ ID: b && b.ID, Judul: $('#bj', bg).value, Tanggal: $('#bt', bg).value, Kategori: $('#bc', bg).value, Ringkasan: $('#br', bg).value, Lokasi: $('#bl', bg).value, Status: $('#bs', bg).value });
  const draw = () => { if (mati) return; $('#bv').innerHTML = `<div class="grid g2">${rows.length ? rows.map(b => `<div class="card col"><div class="row between"><span class="badge info">${esc(b.Kategori)}</span><span class="badge ${b.Status === 'Draft' ? 'warn' : 'ok'}">${esc(b.Status)}</span></div><h3>${esc(b.Judul)}</h3><p class="sub grow">${esc(b.Ringkasan)}</p><div class="row between"><span class="faint" style="font-size:12px">${tglID(b.Tanggal)}${b.Lokasi ? ' · ' + esc(b.Lokasi) : ''}</span><span class="row"><button class="btn sm icon" data-ed="${esc(b.ID)}" aria-label="Ubah">${ico('edit', 'sm')}</button><button class="btn sm icon danger" data-del="${esc(b.ID)}" aria-label="Hapus">${ico('delete', 'sm')}</button></span></div></div>`).join('') : `<div class="card" style="grid-column:1/-1">${kosong('campaign', 'Belum ada pengumuman.')}</div>`}</div>`; };
  const muat = async () => { const r = await api('berita.list'); if (mati) return; if (!r.success) { $('#bv').innerHTML = galat(r.message); return; } rows = r.data.rows; draw(); }; muat();
  $('#add', v).onclick = () => modal({ title: 'Pengumuman baru', wide: true, body: form(), actions: [{ label: 'Batal' }, { label: 'Simpan', cls: 'primary', onClick: async bg => { const r = await api('berita.save', baca(bg)); if (!r.success) { toast(r.message, 'error'); return false; } toast(r.message); muat(); } }] });
  on(v, 'click', '[data-ed]', (e, b) => { const x = rows.find(z => z.ID === b.dataset.ed); modal({ title: 'Ubah pengumuman', wide: true, body: form(x), actions: [{ label: 'Batal' }, { label: 'Simpan', cls: 'primary', onClick: async bg => { const r = await api('berita.save', baca(bg, x)); if (!r.success) { toast(r.message, 'error'); return false; } toast(r.message); muat(); } }] }); });
  on(v, 'click', '[data-del]', async (e, b) => { if (await konfirmasi('Hapus pengumuman ini?', 'Hapus', true)) { const r = await api('berita.hapus', { id: b.dataset.del }); toast(r.message, r.success ? '' : 'error'); muat(); } });
  on(v, 'click', '[data-act=muat-ulang]', muat);
  return () => { mati = true; };
}

/* ---------- Migrasi data ---------- */
function pageMigrasi(v) {
  const SH = [['Master_Santri', 'Data santri'], ['Presensi', 'Presensi'], ['Hafalan_Hanca', 'Hafalan & hanca'], ['Keuangan', 'Keuangan / SPP'], ['Materi', 'Materi']];
  v.innerHTML = judul('Administrasi', 'Migrasi Data', '') + `<div class="grid g-main2"><div class="card col gap-lg"><div class="notice info">${ico('info')}<span>Impor data dari spreadsheet lama. Spreadsheet lama <b>hanya dibaca</b>; proses aman diulang (tidak menggandakan data) dan selalu mulai dengan <b>pindai uji</b>. Akun Google pemilik aplikasi harus punya akses ke spreadsheet lama.</span></div>
    <label class="f">URL atau ID spreadsheet lama<input class="in" id="ms" placeholder="https://docs.google.com/spreadsheets/d/…"></label>
    <div><div class="sub" style="font-weight:600;margin-bottom:6px">Sheet yang diimpor (urutan otomatis)</div><div class="chips">${SH.map(s => `<label class="chk chip on" style="gap:8px"><input type="checkbox" data-sh="${s[0]}" checked><span>${s[1]}</span></label>`).join('')}</div></div>
    <label class="chk"><input type="checkbox" id="mt"><span>Timpa data santri yang sudah ada (nama, kelas, wali, kontak)</span></label><label class="chk"><input type="checkbox" id="ma"><span>Buat akun wali untuk santri baru</span></label>
    <div class="row wrap"><button class="btn primary" id="scan">${ico('search', 'sm')} Pindai uji (tanpa menulis)</button><button class="btn" id="run" disabled>${ico('play_arrow', 'sm')} Jalankan impor</button></div></div><div class="card" id="mr"><h3>Hasil</h3>${kosong('sync_alt', 'Jalankan pindai uji untuk melihat rencana impor.')}</div></div>`;
  const opsi = dry => ({ source: $('#ms').value.trim(), dryRun: dry, sheets: $$('[data-sh]:checked', v).map(c => c.dataset.sh), timpa: $('#mt').checked, buatAkun: $('#ma').checked });
  const hasil = r => { const d = r.data; $('#mr').innerHTML = `<h3>Hasil ${d.dryRun ? 'pindai uji' : 'impor'} — ${esc(d.sumber.nama)}</h3><div class="tbl-wrap mt"><table class="t" style="min-width:0"><thead><tr><th>Sheet</th><th>Baris sumber</th><th>Ditambah</th><th>Diperbarui</th><th>Dilewati</th></tr></thead><tbody>${Object.keys(d.laporan).map(k => { const x = d.laporan[k]; return `<tr><td>${esc(k)}${x.tidakAda ? ' <span class="badge warn">tidak ada</span>' : ''}</td><td>${x.sumber}</td><td><b>${x.ditambah}</b></td><td>${x.diperbarui}</td><td>${x.dilewati}</td></tr>`; }).join('')}</tbody></table></div>${d.peringatan.length ? `<div class="notice mt">${ico('warning')}<ul style="margin:0;padding-left:18px">${d.peringatan.map(p => `<li>${esc(p)}</li>`).join('')}</ul></div>` : ''}`; };
  $('#scan').onclick = async e => { await tombolSibuk(e.currentTarget, async () => { const r = await api('migrasi.jalankan', opsi(true), { timeout: 120000 }); if (!r.success) return toast(r.message, 'error'); hasil(r); $('#run').disabled = false; }); };
  $('#run').onclick = async e => { if (!(await konfirmasi('Jalankan impor sungguhan? Data akan ditulis ke database aplikasi baru.', 'Jalankan impor'))) return; await tombolSibuk(e.currentTarget, async () => { const r = await api('migrasi.jalankan', opsi(false), { timeout: 300000 }); if (!r.success) return toast(r.message, 'error'); hasil(r); toast(r.message); Api.epoch++; if (r.data.akun.length) tampilkanKredensial('Akun wali baru (' + r.data.akun.length + ')', r.data.akun); }); };
  $('#ms').oninput = () => { $('#run').disabled = true; };
}

/* ---------- Pengaturan ---------- */
const GRUP_SETTING = [
  ['Profil madrasah', [['NAMA_MADRASAH', 'Nama madrasah'], ['SLOGAN', 'Slogan'], ['TA_AKTIF', 'Tahun ajaran aktif'], ['AKREDITASI', 'Akreditasi'], ['ALAMAT', 'Alamat'], ['TELP', 'Telepon / WA TU'], ['EMAIL', 'Email'], ['JAM_BELAJAR', 'Jam belajar'], ['HARI_BELAJAR', 'Hari belajar'], ['WA_PPDB', 'WA konsultasi PPDB']]],
  ['Akademik & SPP', [['KELAS_DAFTAR', 'Daftar kelas (pisah koma)'], ['TARIF_SPP', 'Tarif SPP per jenjang (JSON)'], ['JAM_TERLAMBAT', 'Batas terlambat (HH:MM)']]],
  ['Rekening madrasah', [['REK_NAMA_BANK', 'Nama bank'], ['REK_NOMOR', 'Nomor rekening'], ['REK_ATAS_NAMA', 'Atas nama']]],
  ['Berkas', [['BUKTI_LINK_PUBLIK', 'Berkas bisa dibuka lewat tautan (YA/TIDAK)']]]
];
function pagePengaturan(v) {
  let mati = false;
  v.innerHTML = judul('Administrasi', 'Pengaturan Sistem', '') + '<div id="pg">' + skelCards(2) + '</div>';
  (async () => {
    const [r, st] = await Promise.all([api('pengaturan.get'), api('sistem.status')]); if (mati) return; if (!r.success) { $('#pg').innerHTML = galat(r.message); return; }
    const n = r.data.nilai, s = st.data || {};
    $('#pg').innerHTML = `<div class="grid g-main2"><form class="col gap-lg" id="pf">${GRUP_SETTING.map(g => `<div class="card"><h3>${g[0]}</h3><div class="form-grid mt">${g[1].map(k => `<label class="f ${/ALAMAT|SLOGAN|TARIF|KELAS/.test(k[0]) ? 'full' : ''}">${k[1]}<input class="in" data-k="${k[0]}" value="${esc(n[k[0]])}"></label>`).join('')}</div></div>`).join('')}<button class="btn primary" type="submit" style="align-self:flex-start">${ico('save', 'sm')} Simpan pengaturan</button></form>
      <div class="col gap-lg"><div class="card"><h3>Status sistem</h3><div class="col mt"><div class="row between"><span>Versi backend</span><b>${esc(s.versi || '-')}</b></div><div class="row between"><span>Trigger antrean notifikasi</span><span class="badge ${(s.trigger || []).indexOf('prosesAntrianNotif') > -1 ? 'ok' : 'bad'}">${(s.trigger || []).indexOf('prosesAntrianNotif') > -1 ? 'Aktif' : 'Belum dipasang'}</span></div><div class="row between"><span>Keep-warm</span><span class="badge ${(s.trigger || []).indexOf('keepWarm') > -1 ? 'ok' : ''}">${(s.trigger || []).indexOf('keepWarm') > -1 ? 'Aktif' : 'Mati'}</span></div><div class="row between"><span>Token Fonnte</span><span class="badge ${s.fonnteToken ? 'ok' : 'warn'}">${s.fonnteToken ? 'Tersimpan' : 'Belum diisi'}</span></div></div><button class="btn mt" id="perf">${ico('speed', 'sm')} Ukur performa sesi ini</button><div id="pt"></div></div>
      <div class="card"><h3>Keamanan</h3><div class="col mt"><button class="btn" id="dr">${ico('emergency', 'sm')} Ganti kredensial akses darurat</button><button class="btn" id="ka">${ico('devices', 'sm')} Keluarkan saya dari semua perangkat</button></div></div></div></div>`;
    $('#pf').onsubmit = async e => { e.preventDefault(); await tombolSibuk($('#pf button[type=submit]'), async () => { const nilai = {}; $$('[data-k]', $('#pf')).forEach(i => { nilai[i.dataset.k] = i.value; }); const r = await api('pengaturan.save', { nilai }); toast(r.message, r.success ? '' : 'error'); if (r.success) { const m = await api('auth.me'); if (m.success) { Sesi.meta = m.data; Sesi.save(!!localStorage.getItem('mdt.sesi')); } } }); };
    $('#perf').onclick = () => { const p = Perf.summary(); $('#pt').innerHTML = `<div class="tbl-wrap mt"><table class="t" style="min-width:0"><thead><tr><th>Aksi</th><th>n</th><th>Total ms</th><th>Server ms</th></tr></thead><tbody>${p.map(x => `<tr><td>${esc(x.aksi)}</td><td>${x.panggilan}</td><td>${x.rataTotalMs}</td><td>${x.rataServerMs}</td></tr>`).join('') || '<tr><td colspan="4">Belum ada data.</td></tr>'}</tbody></table></div>`; };
    $('#dr').onclick = () => modal({ title: 'Kredensial akses darurat', body: '<label class="f">Kata sandi darurat baru<span class="hint">Minimal 12 karakter, huruf + angka. Simpan di pengelola sandi.</span><input class="in" type="password" id="dn" autocomplete="new-password"></label>', actions: [{ label: 'Batal' }, { label: 'Simpan', cls: 'primary', onClick: async bg => { const r = await api('darurat.rotasi', { baru: $('#dn', bg).value }); toast(r.message, r.success ? '' : 'error'); if (!r.success) return false; } }] });
    $('#ka').onclick = async () => { if (await konfirmasi('Semua perangkat akan dikeluarkan.', 'Keluarkan')) { await api('auth.keluarSemua'); Sesi.clear(); Shell.uid = null; Router.go('/login'); } };
  })();
  on(v, 'click', '[data-act=muat-ulang]', () => Router.render());
  return () => { mati = true; };
}
